"""FacultyCertificate — certificate generated by a faculty member.

Saved in separate collection 'faculty_certificates' instead of 'dept_certificates' or 'guest_certificates'.
"""

from datetime import datetime
from typing import Any, Dict, Optional

from beanie import Document, Indexed, PydanticObjectId
from pydantic import Field


class FacultyCertificate(Document):
    cert_number: Indexed(str, unique=True)  # type: ignore[valid-type]
    session_id: Indexed(PydanticObjectId)   # type: ignore[valid-type]
    faculty_id: PydanticObjectId            # User ID of faculty who generated this

    event_name: str
    recipient_name: str
    recipient_email: Optional[str] = None
    registration_number: Optional[str] = None
    class_name: Optional[str] = None
    contribution: Optional[str] = None
    cert_type: str = "Faculty Certificate"

    row_data: Dict[str, Any] = Field(default_factory=dict)
    png_url: str
    file_path: Optional[str] = None

    status: str = "generated"  # "generated", "emailed", "failed"
    emailed_at: Optional[datetime] = None
    email_error: Optional[str] = None
    created_at: datetime = Field(default_factory=datetime.utcnow)

    class Settings:
        name = "faculty_certificates"
